import { Table, BooleanColumn, ChoiceColumn, ListColumn, ReferenceColumn, ScriptColumn, StringColumn } from '../../db'

export const sys_ws_operation = Table({
    actions: {
        read: true,
        update: false,
        delete: false,
        create: false,
    },
    allowClientScripts: false,
    allowNewFields: false,
    allowUiActions: false,
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        update_synch: true,
    },
    extends: 'sys_metadata',
    label: 'Scripted REST Resource',
    name: 'sys_ws_operation',
    schema: {
        name: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'The name of this API resource. Appears in API documentation.',
                    label: 'Name',
                    plural: 'Names',
                },
            ],
            mandatory: true,
            maxLength: 40,
        }),
        consumes_customized: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Check to customize the request media types supported by this resource',
                    label: 'Override supported request formats',
                    plural: 'Override supported request formats',
                },
            ],
            maxLength: 30,
        }),
        support_trailing_slash: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Enabling allows this resource to be accessed with or without a trailing slash. Example: /resource and /resource/.',
                    label: 'Support Trailing Slash',
                    plural: 'Support Trailing Slashes',
                },
            ],
            maxLength: 30,
        }),
        requires_authentication: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Whether requests must be authenticated to access this resource',
                    label: 'Requires authentication',
                    plural: 'Requires authentications',
                },
            ],
            maxLength: 30,
        }),
        produces_customized: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Check to customize the response media types supported by this resource',
                    label: 'Override supported response formats',
                    plural: 'Override supported response formats',
                },
            ],
            maxLength: 30,
        }),
        produces: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            default: 'javascript:current.produces = current.web_service_definition.produces',
            label: [
                {
                    hint: 'Comma-delimited list of media types this resource can produce',
                    label: 'Supported response formats',
                    plural: 'Supported response formats',
                },
            ],
            maxLength: 200,
        }),
        http_method: ChoiceColumn({
            default: 'GET',
            choices: {
                GET: {
                    label: 'GET',
                    sequence: 10,
                },
                POST: {
                    label: 'POST',
                    sequence: 20,
                },
                PUT: {
                    label: 'PUT',
                    sequence: 30,
                },
                PATCH: {
                    label: 'PATCH',
                    sequence: 40,
                },
                DELETE: {
                    label: 'DELETE',
                    sequence: 50,
                },
            },
            dropdown: 'dropdown_without_none',
            label: [
                {
                    hint: 'The HTTP method that maps to this resource',
                    label: 'HTTP method',
                    plural: 'HTTP methods',
                },
            ],
            mandatory: true,
            maxLength: 40,
        }),
        requires_snc_internal_role: BooleanColumn({
            default: true,
            label: 'Requires SNC Internal',
            maxLength: 40,
        }),
        consumes: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            default: 'javascript:current.consumes = current.web_service_definition.consumes',
            label: [
                {
                    hint: 'Comma-delimited list of media types this resource can consume',
                    label: 'Supported request formats',
                    plural: 'Supported request formats',
                },
            ],
            maxLength: 200,
        }),
        web_service_version: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                ref_ac_order_by: 'version',
            },
            cascadeRule: 'delete',
            label: [
                {
                    hint: 'The version this resource belongs to',
                    label: 'API version',
                    plural: 'API versions',
                },
            ],
            // Relaxing mandatory field to false as it is not always set on instance either.
            mandatory: false,
            maxLength: 32,
            referenceTable: 'sys_ws_version',
            referenceQual: "javascript:'web_service_definition=' + current.web_service_definition",
        }),
        requires_acl_authorization: BooleanColumn({
            label: [
                {
                    hint: 'Enforce ACLs when this resource is accessed',
                    label: 'Requires ACL authorization',
                    plural: 'Requires ACL authorizations',
                },
            ],
            maxLength: 30,
        }),
        request_example: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'An example request payload. Appears in API documentation.',
                    label: 'Request body example',
                    plural: 'Request body examples',
                },
            ],
            maxLength: 16777215,
        }),
        operation_uri: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: `function normalizePath(path) {
	// replace repeating '/' chars with a single '/'
	path = path.replace(/\\/+/g, '/');
	path = path.trim();
	// remove the trailing '/' if present
	if (path.charAt(path.length-1) == '/')
		path = path.substring(0, path.length-1);
	
	return path;
}

function resolveOperationUri() {
	if (current.web_service_definition != '') {
		var versionId = '';
		if (current.web_service_version != '')
			versionId = current.web_service_version.version_id + '/';
		
		var endpointPath = '/api/' + current.web_service_definition.namespace + '/' + versionId
		+ current.web_service_definition.service_id
		+ '/' + current.relative_path;
		
		return normalizePath(endpointPath);
	}
	return '';
}

current.operation_uri = resolveOperationUri();`,
            },
            label: [
                {
                    hint: 'The resolved path of this resource including base API path, version, and relative path',
                    label: 'Resource path',
                    plural: 'Resource paths',
                },
            ],
            maxLength: 255,
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
        enforce_acl: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            default: 'javascript:current.enforce_acl = current.web_service_definition.enforce_acl',
            label: [
                {
                    hint: 'The ACL authorization to enforce when accessing this resource If not set, the default ACL authorization from the parent API is enforced if it is set.',
                    label: 'ACLs',
                    plural: 'ACLs',
                },
            ],
            maxLength: 16777215,
            referenceTable: 'sys_security_acl',
            referenceQual: 'type=REST_Endpoint^operation=execute^EQ',
            useReferenceQualifier: 'simple',
        }),
        web_service_definition: ReferenceColumn({
            attributes: {
                readonly_clickthrough: true,
            },
            cascadeRule: 'delete',
            label: [
                {
                    hint: 'The parent API this resource belongs to',
                    label: 'API definition',
                    plural: 'API definitions',
                },
            ],
            mandatory: true,
            maxLength: 32,
            readOnly: true,
            readOnlyOption: 'instance_configured',
            referenceTable: 'sys_ws_definition',
        }),
        short_description: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'The description of the resource. Appears in API documentation.',
                    label: 'Short description',
                    plural: 'Short descriptions',
                },
            ],
            maxLength: 80,
        }),
        active: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Activates the resource Inactive resources cannot serve requests.',
                    label: 'Active',
                    plural: 'Active',
                },
            ],
            maxLength: 30,
        }),
        relative_path: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            default: '/',
            label: [
                {
                    hint: 'The path of this resource relative to the base API path. Can contain templatized path parameters such as /{id}.',
                    label: 'Relative path',
                    plural: 'Relative paths',
                },
            ],
            maxLength: 255,
        }),
        operation_script: ScriptColumn({
            default: `(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {\r
\r
    // implement resource here\r
\r
})(request, response);`,
            label: [
                {
                    hint: 'The script that implements the resource',
                    label: 'Script',
                    plural: 'Scripts',
                },
            ],
            mandatory: true,
            maxLength: 16777215,
        }),
        default_operation_uri: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: `function normalizePath(path) {
	// replace repeating '/' chars with a single '/'
	path = path.replace(/\\/+/g, '/');
	path = path.trim();
	// remove the trailing '/' if present
	if (path.charAt(path.length-1) == '/') {
		path = path.substring(0, path.length-1);
	}
	return path;
}

function operationInDefaultVersion() {
	return (current.web_service_version != '' &&
		current.web_service_definition.default_version == current.web_service_version.version_id);
}

function resolveDefaultOperationPath() {
	// if not versioned or operation belongs to default version
	if (operationInDefaultVersion()) {
		var endpointPath = current.web_service_definition.base_uri + '/' + current.relative_path;
		return normalizePath(endpointPath);
	}
	
	return '';
}

current.default_operation_uri = resolveDefaultOperationPath();`,
            },
            label: [
                {
                    hint: 'The resolved default (non-versioned) path of this resource including base API path, version, and relative path, if this resource belongs to the default API version',
                    label: 'Default resource path',
                    plural: 'Default resource paths',
                },
            ],
            maxLength: 255,
            readOnly: true,
            readOnlyOption: 'instance_configured',
        }),
    },
    textIndex: true,
})
